// HasTask applies the HasEdge predicate on the "task" edge.
func HasTask() predicate.StageRun {
	return predicate.StageRun(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, TaskTable, TaskColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasTaskWith applies the HasEdge predicate on the "task" edge with a given conditions (other predicates).
func HasTaskWith(preds ...predicate.Task) predicate.StageRun {
	return predicate.StageRun(func(s *sql.Selector) {
		step := newTaskStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasPermissionRequests applies the HasEdge predicate on the "permission_requests" edge.
func HasPermissionRequests() predicate.StageRun {
	return predicate.StageRun(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, PermissionRequestsTable, PermissionRequestsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasPermissionRequestsWith applies the HasEdge predicate on the "permission_requests" edge with a given conditions (other predicates).
func HasPermissionRequestsWith(preds ...predicate.PermissionRequest) predicate.StageRun {
	return predicate.StageRun(func(s *sql.Selector) {
		step := newPermissionRequestsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.StageRun) predicate.StageRun {
	return predicate.StageRun(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.StageRun) predicate.StageRun {
	return predicate.StageRun(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.StageRun) predicate.StageRun {
	return predicate.StageRun(sql.NotPredicates(p))
}
